"""Public customer selection generated by the original reviewed merchant plan."""
from __future__ import annotations

import os
import re
from urllib.parse import urlsplit

from ._storage import copy_json, object_file, require

SELECTION_SCHEMA = "stellar-forge.tenderly-customer-selection.v1"


def normalize_selection(value: dict) -> dict:
    keys = {"schema", "resource", "method", "networkId", "simulationType", "planSha256", "maxResponseBytes"}
    require(isinstance(value, dict) and set(value) == keys
            and value.get("schema") == SELECTION_SCHEMA and value.get("method") == "POST",
            "TENDERLY_CUSTOMER_SELECTION_INVALID")
    resource = value.get("resource")
    require(isinstance(resource, str) and len(resource) <= 4096
            and not any(ord(char) <= 32 for char in resource), "TENDERLY_CUSTOMER_RESOURCE_INVALID")
    try:
        url = urlsplit(resource)
        valid = (url.scheme == "https" and bool(url.hostname) and not url.username and not url.password
                 and not url.query and not url.fragment and bool(url.path)
                 and url.geturl() == resource and url.port != 443)
    except ValueError:
        valid = False
    require(valid, "TENDERLY_CUSTOMER_RESOURCE_INVALID")
    require(isinstance(value.get("networkId"), str)
            and bool(re.fullmatch(r"[1-9][0-9]{0,19}", value["networkId"]))
            and value.get("simulationType") in ("quick", "abi", "full")
            and isinstance(value.get("planSha256"), str)
            and bool(re.fullmatch(r"[0-9a-f]{64}", value["planSha256"]))
            and type(value.get("maxResponseBytes")) is int
            and 1024 <= value["maxResponseBytes"] <= 1_048_576, "TENDERLY_CUSTOMER_SELECTION_INVALID")
    return copy_json(value)


def load_selection(value) -> dict | None:
    if value is None:
        return None
    return normalize_selection(object_file(value) if isinstance(value, (str, os.PathLike)) else value)

